-- Generated by hyprconf2lua v1.4.0 and manually fixed
---@module 'hl'

-- ==============================================================================
-- 🖥️ MONITORS
-- ==============================================================================
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = 1,
})

-- ==============================================================================
-- ⌨️ INPUT DEVICES
-- ==============================================================================
hl.config({
    input = {
        kb_layout = "us,it",
        kb_options = "grp:alt_space_toggle",
        follow_mouse = 1,
        sensitivity = 0,
        touchpad = {
            natural_scroll = true,
            tap_to_click = true,
        },
    },
})

-- ==============================================================================
-- 🎨 GENERAL & DECORATION
-- ==============================================================================
hl.config({
    general = {
        gaps_in = 5,
        gaps_out = 10,
        border_size = 2,
        layout = "dwindle",
        col = {
            active_border = "rgb(cdd6f4)",
            inactive_border = "rgba(595959aa)",
        },
    },
})

hl.config({
    decoration = {
        rounding = 5,
        blur = {
            enabled = true,
            size = 5,
            passes = 1,
            vibrancy = 0.1696,
            new_optimizations = true,
        },
    },
})

hl.config({
    misc = {
        disable_hyprland_logo = true,
    },
})

-- ==============================================================================
-- 💫 ANIMATIONS
-- ==============================================================================
hl.config({
    animations = {
        enabled = true,
    },
})

hl.curve("myBezier", {
    type = "bezier",
    points = { { 0.10, 0.9 }, { 0.1, 1.05 } },
})

hl.animation({ leaf = "windows", enabled = true, speed = 10, bezier = "myBezier", style = "slide" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 7, bezier = "myBezier", style = "slide" })
hl.animation({ leaf = "border", enabled = true, speed = 10, bezier = "default" })
hl.animation({ leaf = "fade", enabled = true, speed = 7, bezier = "default" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 6, bezier = "default" })
-- ==============================================================================
-- 🪟 LAYOUTS & GESTURES
-- ==============================================================================
hl.config({
    dwindle = {
        preserve_split = true,
    },
    master = {
        new_status = "master",
    },
})

hl.gesture({
    ["fingers"] = 3,
    ["direction"] = "horizontal",
    ["action"] = "workspace",
})

-- ==============================================================================
-- 📜 WINDOW RULES
-- ==============================================================================
-- Floating Rules
hl.window_rule({ match = { class = "^(pavucontrol)$" }, float = true })
hl.window_rule({ match = { class = "^(blueman-manager)$" }, float = true })
hl.window_rule({ match = { class = "^(nm-connection-editor)$" }, float = true })
hl.window_rule({ match = { class = "^(chromium)$" }, float = true })
hl.window_rule({ match = { class = "^(thunar)$" }, float = true })
hl.window_rule({ match = { title = "^(btop)$" }, float = true })
hl.window_rule({ match = { title = "^(update-sys)$" }, float = true })

-- Custom Animations (Fixed from TODOs)
hl.window_rule({ match = { class = "^(kitty)$", title = "^(update-sys)$" }, animation = "popin" })
hl.window_rule({ match = { class = "^(thunar)$" }, animation = "popin" })
hl.window_rule({ match = { class = "^(wofi)$" }, animation = "slide" })

-- Style & Opacity
hl.window_rule({ match = { class = "^(wofi)$" }, opacity = "1 1" })
hl.window_rule({ match = { float = 1 }, rounding = 10 })

-- Positioning
hl.window_rule({ match = { class = "^(wofi)$", title = "^(clippick)$" }, move = { "100%-433", 53 } })

-- ==============================================================================
-- 🌫️ LAYER RULES
-- ==============================================================================
-- Blur Background (Syntax Fixed)
hl.layer_rule({ match = { namespace = "^(swaync-control-center)$" }, blur = true })
hl.layer_rule({ match = { namespace = "^(swaync-notification-window)$" }, blur = true })
hl.layer_rule({ match = { namespace = "^(logout_dialog)$" }, blur = true })
hl.layer_rule({ match = { namespace = "^(wofi)$" }, blur = true })
hl.layer_rule({ match = { namespace = "^(waybar)$" }, blur = true })
hl.layer_rule({ match = { namespace = "^(lockscreen)$" }, blur = true })

-- Ignore Alpha
hl.layer_rule({ match = { namespace = "swaync-control-center" }, ignore_alpha = 0 })
hl.layer_rule({ match = { namespace = "swaync-notification-window" }, ignore_alpha = 0 })

-- ==============================================================================
-- ⌨️ KEYBINDINGS
-- ==============================================================================
local mainMod = "SUPER"

-- Essential Apps & Actions
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd("kitty"))
hl.bind(mainMod .. " + SPACE", hl.dsp.exec_cmd("wofi"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd("thunar"))
hl.bind(mainMod .. " + S", hl.dsp.exec_cmd("grim -g \"$(slurp)\" - | swappy -f -"))
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("swaylock"))
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("wlogout --protocol layer-shell"))
hl.bind(mainMod .. " + SHIFT + M", hl.dsp.exit())

-- Window Management
hl.bind(mainMod .. " + F4", hl.dsp.window.close())
hl.bind(mainMod .. " + V", hl.dsp.window.float())
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())

-- Focus Navigation
hl.bind(mainMod .. " + left", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down", hl.dsp.focus({ direction = "down" }))

-- Workspace Navigation
hl.bind(mainMod .. " + 1", hl.dsp.focus({ workspace = 1 }))
hl.bind(mainMod .. " + 2", hl.dsp.focus({ workspace = 2 }))
hl.bind(mainMod .. " + 3", hl.dsp.focus({ workspace = 3 }))
hl.bind(mainMod .. " + 4", hl.dsp.focus({ workspace = 4 }))
hl.bind(mainMod .. " + 5", hl.dsp.focus({ workspace = 5 }))
hl.bind(mainMod .. " + 6", hl.dsp.focus({ workspace = 6 }))
hl.bind(mainMod .. " + 7", hl.dsp.focus({ workspace = 7 }))
hl.bind(mainMod .. " + 8", hl.dsp.focus({ workspace = 8 }))
hl.bind(mainMod .. " + 9", hl.dsp.focus({ workspace = 9 }))
hl.bind(mainMod .. " + 0", hl.dsp.focus({ workspace = 10 }))

-- Move Active Window to Workspace
hl.bind(mainMod .. " + SHIFT + 1", hl.dsp.window.move({ workspace = 1 }))
hl.bind(mainMod .. " + SHIFT + 2", hl.dsp.window.move({ workspace = 2 }))
hl.bind(mainMod .. " + SHIFT + 3", hl.dsp.window.move({ workspace = 3 }))
hl.bind(mainMod .. " + SHIFT + 4", hl.dsp.window.move({ workspace = 4 }))
hl.bind(mainMod .. " + SHIFT + 5", hl.dsp.window.move({ workspace = 5 }))
hl.bind(mainMod .. " + SHIFT + 6", hl.dsp.window.move({ workspace = 6 }))
hl.bind(mainMod .. " + SHIFT + 7", hl.dsp.window.move({ workspace = 7 }))
hl.bind(mainMod .. " + SHIFT + 8", hl.dsp.window.move({ workspace = 8 }))
hl.bind(mainMod .. " + SHIFT + 9", hl.dsp.window.move({ workspace = 9 }))
hl.bind(mainMod .. " + SHIFT + 0", hl.dsp.window.move({ workspace = 10 }))

-- Scroll Through Workspaces
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up", hl.dsp.focus({ workspace = "e-1" }))

-- Mouse Window Manipulation (Drag)
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- ==============================================================================
-- 🚀 AUTOSTART (exec-once)
-- ==============================================================================
hl.on("hyprland.start", function()
    hl.exec_cmd("~/.config/hypr/scripts/xdg-portal-hyprland")
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("waybar")
    hl.exec_cmd("blueman-applet")
    hl.exec_cmd("nm-applet --indicator")
    hl.exec_cmd("awww-daemon")
end)
